mapper.select:
${pagingTop} SELECT homepage_id, quick_idx, menu_name, link_url, link_target, org_file_name, server_file_name, file_extension, file_size, view_yn, link_use_yn, print_seq, add_id, add_date FROM CMS_QUICK_MENU WHERE homepage_id = #{homepage_id}
AND ${search_type} LIKE '%'||#{search_text}||'%'
ORDER BY print_seq ASC ${pagingBottom}

mapper.update:
UPDATE CMS_QUICK_MENU SET menu_name = #{menu_name}, link_url = #{link_url}, link_target = #{link_target},
org_file_name = #{org_file_name}, server_file_name = #{server_file_name}, file_extension = #{file_extension}, file_size = #{file_size},
view_yn = #{view_yn}, link_use_yn = #{link_use_yn}, print_seq = #{print_seq}, modify_id = #{modify_id}, modify_date = SYSDATE WHERE homepage_id = #{homepage_id} AND quick_idx = #{quick_idx}

mapper.delete:
DELETE FROM
	CMS_QUICK_MENU
WHERE
	homepage_id = #{homepage_id}
AND	quick_idx = #{quick_idx}
